#include <iostream>
#include <fstream>
#include <string>
using namespace std;

class Aluno {
public:
    string nome;
    int idade;
    float mediacurso;

    void setNome(string n) {
        nome = n;
    }

    void setIdade(int i) {
        idade = i;
    }

    void setMediaCurso(float m) {
        mediacurso = m;
    }

    string getNome() {
        return nome;
    }

    int getIdade() {
        return idade;
    }

    float getMediaCurso() {
        return mediacurso;
    }
};

int main() {
    Aluno alunos[5];
    char opcao;

    do {
        cout << "Escolha uma opção:" << endl;
        cout << "A - Instanciar a classe com 5 alunos e com valores à sua escolha." << endl;
        cout << "B - Gravar num ficheiro os valores instanciados em A." << endl;
        cout << "C - Ler os valores do ficheiro criados em B e instancia-os na estrutura de 1." << endl;
        cout << "D - Imprimir na consola a lista de alunos instanciados." << endl;
        cout << "E - Sair do menu." << endl;

        cin >> opcao;

        switch (opcao) {
            case 'A':
                for (int i = 0; i < 5; i++) {
                    string nome;
                    int idade;
                    float media;

                    cout << "Insira o nome do aluno " << i + 1 << ": ";
                    cin >> nome;

                    cout << "Insira a idade do aluno " << i + 1 << ": ";
                    cin >> idade;

                    do {
                        cout << "Insira a média do aluno " << i + 1 << ": ";
                        cin >> media;
                    } while (media < 0 || media > 20);

                    alunos[i].setNome(nome);
                    alunos[i].setIdade(idade);
                    alunos[i].setMediaCurso(media);
                }
                break;

            case 'B':
                ofstream myfile("alunos.txt");

                if (myfile.is_open()) {
                    for (int i = 0; i < 5; i++) {
                        myfile << alunos[i].getNome() << "," << alunos[i].getIdade() << "," << alunos[i].getMediaCurso() << endl;
                    }

                    myfile.close();
                } else {
                    cout << "Não foi possível abrir o ficheiro." << endl;
                }
                break;

            case 'C':
            	ifstream myfile2("alunos.txt");

                if (myfile2.is_open()) {
                    string line;

                    for (int i = 0; getline(myfile2, line); i++) {
                        string nome = line.substr(0, line.find(","));
                        line.erase(0, line.find(",") + 1);

                        int idade = stoi(line.substr(0, line.find(",")));
                        line.erase(0, line.find(",") + 1);

                        float media = stof(line);

                        alunos[i].setNome(nome);
                        alunos[i].setIdade(idade);
                        alunos[i].setMediaCurso(media);
                    }

                    myfile2.close();
                } else {
                    cout << "Não foi possível abrir o ficheiro." << endl;
                }
                break;

            case 'D':
                for (int i = 0; i < 5; i++) {
                    cout << alunos[i].getNome() << "\t" << alunos[i].getIdade() << "\t" << alunos[i].getMediaCurso() << endl;
                }
                break;

            case 'E':
                break;

            default:
                cout << "Opção inválida" << endl;
        }
    } while (opcao != 'E');

    return 0;
}

